const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define southern Iran region
  const southernIran = ee.Geometry.Polygon([
    [[48, 25], [60, 25], [60, 32], [48, 32], [48, 25]]
  ]);

  const date1 = '2021-12-14';
  const date2 = '2022-01-07';

  // Function to mask clouds in Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Get Sentinel-2 data for date 1
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(southernIran)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .map(maskS2clouds);

  let size1 = await col1.size().getInfo();

  if (size1 === 0) {
    col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(southernIran)
      .filterDate(ee.Date(date1).advance(-5, 'day'), ee.Date(date1).advance(5, 'day'))
      .map(maskS2clouds);
    size1 = await col1.size().getInfo();
  }

  // Get Sentinel-2 data for date 2
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(southernIran)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .map(maskS2clouds);

  let size2 = await col2.size().getInfo();

  if (size2 === 0) {
    col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(southernIran)
      .filterDate(ee.Date(date2).advance(-5, 'day'), ee.Date(date2).advance(5, 'day'))
      .map(maskS2clouds);
    size2 = await col2.size().getInfo();
  }

  console.log(`Dec 2021 Images: ${size1}, Jan 2022 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("No data available for one or both dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate MNDWI (Modified Normalized Difference Water Index)
  function addMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  const img1 = col1.map(addMNDWI).median();
  const img2 = col2.map(addMNDWI).median();

  // Water mask: MNDWI > 0
  const water1 = img1.select('MNDWI').gt(0);
  const water2 = img2.select('MNDWI').gt(0);

  // Count water pixels
  const stats1 = await water1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: southernIran,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await water2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: southernIran,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels1 = stats1.MNDWI;
  const waterPixels2 = stats2.MNDWI;

  console.log(`Dec 2021 Water Pixels: ${waterPixels1}`);
  console.log(`Jan 2022 Water Pixels: ${waterPixels2}`);

  if (waterPixels1 === null || waterPixels2 === null || 
      waterPixels1 === undefined || waterPixels2 === undefined) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (waterPixels1 === 0 && waterPixels2 === 0) {
    console.log("No valid water pixels detected for both dates.");
    console.log("<answer>C2</answer>");
    return;
  }

  const percentChange = ((waterPixels2 - waterPixels1) / waterPixels1 * 100).toFixed(2);
  console.log(`Change: ${percentChange}%`);

  if (waterPixels2 > waterPixels1) {
    console.log("Surface water extent increased.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Surface water extent did not increase.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
